package com.example.productinventory.service;
import com.example.productinventory.dto.ProductRequest; import com.example.productinventory.exception.ResourceNotFoundException; import com.example.productinventory.model.Product; import com.example.productinventory.repository.ProductRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service @Transactional public class ProductService { private final ProductRepository repo; public ProductService(ProductRepository r){repo=r;} public Product createProduct(ProductRequest r){return repo.save(new Product(r.name().trim(),r.description().trim(),r.price(),r.quantity(),r.category().trim()));} @Transactional(readOnly=true) public List<Product> getAllProducts(){return repo.findAll();} @Transactional(readOnly=true) public Product getProductById(Long id){return find(id);} public Product updateProduct(Long id,ProductRequest r){Product p=find(id);p.update(r.name().trim(),r.description().trim(),r.price(),r.quantity(),r.category().trim());return repo.save(p);} public void deleteProduct(Long id){repo.delete(find(id));} private Product find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found with id: "+id));} }